mapper.insert:
INSERT INTO tms_carrier (
    carrier_id, tenant_id, code, name, country_code, type, status, contact_person, phone,
    api_enabled, featured, authorization_status, authorization_valid_until, last_authorized_at,
    created_at, updated_at
)
VALUES (
    #{carrierId}, #{tenantId}, #{code}, #{name}, #{countryCode}, #{type}, #{status}, #{contactPerson}, #{phone},
    #{apiEnabled}, #{featured}, #{authorizationStatus}, #{authorizationValidUntil}, #{lastAuthorizedAt},
    #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT carrier_id, tenant_id, code, name, country_code, type, status, contact_person, phone,
       api_enabled, featured, authorization_status, authorization_valid_until, last_authorized_at,
       created_at, updated_at
FROM tms_carrier
WHERE tenant_id = #{tenantId}
  AND carrier_id = #{carrierId}

SELECT carrier_id, tenant_id, code, name, country_code, type, status, contact_person, phone,
       api_enabled, featured, authorization_status, authorization_valid_until, last_authorized_at,
       created_at, updated_at
FROM tms_carrier
WHERE tenant_id = #{tenantId}
  AND code = #{code}

SELECT tenant_id, event_id, shipment_id, status, location, description, occurred_at
FROM tms_tracking_event
WHERE shipment_id = #{shipmentId}
  AND tenant_id = #{tenantId}
ORDER BY occurred_at ASC

