INSERT INTO tms_shipping_cost (
    cost_id, tenant_id, shipment_id, carrier_id, freight_cost, fuel_surcharge, other_fees, total_cost, currency, created_at
)
VALUES (
    #{costId}, #{tenantId}, #{shipmentId}, #{carrierId}, #{freightCost}, #{fuelSurcharge}, #{otherFees}, #{totalCost}, #{currency}, #{createdAt}
)

mapper.select:
SELECT cost_id, tenant_id, shipment_id, carrier_id, freight_cost, fuel_surcharge, other_fees, total_cost, currency, created_at
FROM tms_shipping_cost
WHERE tenant_id = #{tenantId}
  AND carrier_id = #{carrierId}
ORDER BY created_at DESC

SELECT cost_id, tenant_id, shipment_id, carrier_id, freight_cost, fuel_surcharge, other_fees, total_cost, currency, created_at
FROM tms_shipping_cost
WHERE tenant_id = #{tenantId}
  AND shipment_id = #{shipmentId}
ORDER BY created_at DESC
LIMIT 1

