INSERT INTO tms_shipping_method (
    method_id, tenant_id, carrier_id, method_code, method_name, transport_mode, rate_type,
    enabled, estimated_days_min, estimated_days_max, created_at, updated_at
)
VALUES (
    #{methodId}, #{tenantId}, #{carrierId}, #{methodCode}, #{methodName}, #{transportMode}, #{rateType},
    #{enabled}, #{estimatedDaysMin}, #{estimatedDaysMax}, #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT method_id, tenant_id, carrier_id, method_code, method_name, transport_mode, rate_type,
       enabled, estimated_days_min, estimated_days_max, created_at, updated_at
FROM tms_shipping_method
WHERE tenant_id = #{tenantId}
  AND method_id = #{methodId}

SELECT method_id, tenant_id, carrier_id, method_code, method_name, transport_mode, rate_type,
       enabled, estimated_days_min, estimated_days_max, created_at, updated_at
FROM tms_shipping_method
WHERE tenant_id = #{tenantId}
  AND carrier_id = #{carrierId}
  AND method_code = #{methodCode}

SELECT method_id, tenant_id, carrier_id, method_code, method_name, transport_mode, rate_type,
       enabled, estimated_days_min, estimated_days_max, created_at, updated_at
FROM tms_shipping_method
WHERE tenant_id = #{tenantId}
  AND carrier_id = #{carrierId}
ORDER BY method_code ASC

