INSERT INTO tms_shipping_rate (
    rate_id, tenant_id, method_id, origin_country, destination_country, zone_code,
    weight_min_kg, weight_max_kg, base_cost, cost_per_kg, currency,
    effective_from, effective_to, created_at, updated_at
)
VALUES (
    #{rateId}, #{tenantId}, #{methodId}, #{originCountry}, #{destinationCountry}, #{zoneCode},
    #{weightMinKg}, #{weightMaxKg}, #{baseCost}, #{costPerKg}, #{currency},
    #{effectiveFrom}, #{effectiveTo}, #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT rate_id, tenant_id, method_id, origin_country, destination_country, zone_code,
       weight_min_kg, weight_max_kg, base_cost, cost_per_kg, currency,
       effective_from, effective_to, created_at, updated_at
FROM tms_shipping_rate
WHERE tenant_id = #{tenantId}
  AND rate_id = #{rateId}

