UPDATE tms_shipping_batch
SET shipment_ids = #{shipmentIds},
    status = #{status},
    updated_at = #{updatedAt}
WHERE batch_id = #{batchId}
  AND tenant_id = #{tenantId}

mapper.select:
SELECT batch_id, tenant_id, carrier_id, shipment_ids, status, created_at, updated_at
FROM tms_shipping_batch
WHERE tenant_id = #{tenantId}
  AND batch_id = #{batchId}
